SELECT '--- 블랙 쌍의 실제 송출(창 전체) ---' AS x;
SELECT COUNT(*) AS pairs_in_dim, SUM(d.imp) AS imp, SUM(d.clk) AS clk, SUM(d.cost) AS cost
FROM naver_search_term_dim_daily d JOIN bl ON bl.adgroup_id=d.adgroup_id AND bl.media=d.dim_value
WHERE d.dim_type='m';
SELECT '--- 비-블랙 쌍(같은 그룹집합) ---' AS x;
SELECT COUNT(*) AS pairs_in_dim, SUM(d.imp) AS imp, SUM(d.clk) AS clk, SUM(d.cost) AS cost
FROM naver_search_term_dim_daily d
WHERE d.dim_type='m' AND d.adgroup_id IN (SELECT DISTINCT adgroup_id FROM bl)
  AND NOT EXISTS (SELECT 1 FROM bl WHERE bl.adgroup_id=d.adgroup_id AND bl.media=d.dim_value);
SELECT '--- 블랙인데 송출된 상위 (adgroup,media) ---' AS x;
SELECT d.adgroup_id, d.dim_value, COUNT(*) rows_, SUM(d.imp) imp, SUM(d.clk) clk, SUM(d.cost) cost,
       MIN(d.ad_date) d0, MAX(d.ad_date) d1
FROM naver_search_term_dim_daily d JOIN bl ON bl.adgroup_id=d.adgroup_id AND bl.media=d.dim_value
WHERE d.dim_type='m' GROUP BY 1,2 ORDER BY SUM(d.cost) DESC, SUM(d.imp) DESC LIMIT 15;
SELECT '--- 창 재확인 ---' AS x;
SELECT COUNT(*) rows_, COUNT(DISTINCT ad_date) days_, MIN(ad_date) d0, MAX(ad_date) d1,
       COUNT(DISTINCT adgroup_id) grps FROM naver_search_term_dim_daily WHERE dim_type='m';
